const startTyping=()=>{const e=document.querySelector("#hero-typing-text"),n="o padrão moderno.";let t=0;if(e){e.innerHTML="";function s(){t<n.length&&(e.innerHTML+=n.charAt(t),t++,setTimeout(s,100))}setTimeout(s,500)}};document.readyState==="complete"||document.readyState==="interactive"?startTyping():document.addEventListener("DOMContentLoaded",startTyping);function copyToClipboard(e){navigator.clipboard.writeText(e).then(()=>{const e=document.getElementById("copy-toast");e.classList.remove("opacity-0"),e.classList.add("opacity-100"),setTimeout(()=>{e.classList.remove("opacity-100"),e.classList.add("opacity-0")},2e3)}).catch(e=>{console.error("Erro ao copiar: ",e)})}